	('FEEDBACK', '1.1', 'DISABLED', 'INFORMATION SCHEMA', '130101.0', NULL, NULL, 'Sergei Golubchik', 'MariaDB User Feedback Plugin', 'GPL', 'OFF', 'Stable', '1.1'),
