INSERT INTO `REFERENTIAL_CONSTRAINTS` (`CONSTRAINT_CATALOG`, `CONSTRAINT_SCHEMA`, `CONSTRAINT_NAME`, `UNIQUE_CONSTRAINT_CATALOG`, `UNIQUE_CONSTRAINT_SCHEMA`, `UNIQUE_CONSTRAINT_NAME`, `MATCH_OPTION`, `UPDATE_RULE`, `DELETE_RULE`, `TABLE_NAME`, `REFERENCED_TABLE_NAME`) VALUES
	('def', 'hospital', '1', 'def', 'hospital', 'PRIMARY', 'NONE', 'RESTRICT', 'RESTRICT', 'accounts', 'staff'),
	('def', 'hospital', '1', 'def', 'hospital', 'PRIMARY', 'NONE', 'RESTRICT', 'RESTRICT', 'appointments', 'patients'),
	('def', 'hospital', '2', 'def', 'hospital', 'PRIMARY', 'NONE', 'RESTRICT', 'RESTRICT', 'appointments', 'staff'),
	('def', 'hospital', '1', 'def', 'hospital', 'PRIMARY', 'NONE', 'RESTRICT', 'RESTRICT', 'audit_log', 'accounts'),
