INSERT INTO `SYSTEM_VARIABLES` (`VARIABLE_NAME`, `SESSION_VALUE`, `GLOBAL_VALUE`, `GLOBAL_VALUE_ORIGIN`, `DEFAULT_VALUE`, `VARIABLE_SCOPE`, `VARIABLE_TYPE`, `VARIABLE_COMMENT`, `NUMERIC_MIN_VALUE`, `NUMERIC_MAX_VALUE`, `NUMERIC_BLOCK_SIZE`, `ENUM_VALUE_LIST`, `READ_ONLY`, `COMMAND_LINE_ARGUMENT`, `GLOBAL_VALUE_PATH`, `IS_DEPRECATED`, `DEPRECATED_REPLACEMENT`) VALUES
	('BINLOG_GTID_INDEX_PAGE_SIZE', NULL, '4096', 'COMPILE-TIME', '4096', 'GLOBAL', 'INT UNSIGNED', 'Page size to use for the binlog GTID index', '64', '16777216', '1', NULL, 'NO', 'REQUIRED', NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enable the performance schema', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL, 'NO', NULL),
	('PATH', 'CURRENT_SCHEMA', 'CURRENT_SCHEMA', 'COMPILE-TIME', '', 'SESSION', 'VARCHAR', 'Comma-separated list of schema names that defines the search order for stored routines', NULL, NULL, NULL, NULL, 'NO', NULL, NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA_SETUP_OBJECTS_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'INT', 'Maximum number of rows in SETUP_OBJECTS', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
	('BINLOG_SPACE_LIMIT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Alias for max_binlog_total_size. Compatibility with Percona server', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA_EVENTS_WAITS_HISTORY_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'INT', 'Number of rows per thread in EVENTS_WAITS_HISTORY. Use 0 to disable, -1 for automated sizing', '-1', '1024', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA_DIGESTS_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'INT', 'Size of the statement digest. Use 0 to disable, -1 for automated sizing', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA_MAX_COND_CLASSES', NULL, '90', 'COMPILE-TIME', '90', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of condition instruments', '0', '256', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
	('CHECK_CONSTRAINT_CHECKS', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'check_constraint_checks', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL, 'NO', NULL),
	('PERFORMANCE_SCHEMA_MAX_COND_INSTANCES', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'INT', 'Maximum number of instrumented condition objects. Use 0 to disable, -1 for automated sizing', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
	('INNODB_FLUSH_LOG_AT_TIMEOUT', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Write and flush logs every (n) second', '0', '2700', '0', NULL, 'NO', 'OPTIONAL', NULL, 'NO', NULL),
