	('LOG_QUERIES_NOT_USING_INDEXES', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Log queries that are executed without benefit of any index to the slow log if it is open. Same as log_slow_filter=\'not_using_index\'', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL, 'NO', NULL),
	('JOIN_BUFFER_SIZE', '262144', '262144', 'COMPILE-TIME', '262144', 'SESSION', 'BIGINT UNSIGNED', 'The size of the buffer that is used for joins', '128', '18446744073709551615', '128', NULL, 'NO', 'REQUIRED', NULL, 'NO', NULL),
