	('PERFORMANCE_SCHEMA_MAX_THREAD_CLASSES', NULL, '50', 'COMPILE-TIME', '50', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of thread instruments', '0', '256', '1', NULL, 'YES', 'REQUIRED', NULL, 'NO', NULL),
