	('HAVE_SYMLINK', NULL, 'NO', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If symbolic link support is enabled, will be set to YES, otherwise will be set to NO. Required for the INDEX DIRECTORY and DATA DIRECTORY table options (see CREATE TABLE) and Windows symlink support. Will be set to DISABLED if the server is started with the --skip-symbolic-links option', NULL, NULL, NULL, NULL, 'YES', NULL, NULL, 'NO', NULL),
	('BINLOG_COMMIT_WAIT_COUNT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'If non-zero, binlog write will wait at most binlog_commit_wait_usec microseconds for at least this many commits to queue up for group commit to the binlog. This can reduce I/O on the binlog and provide increased opportunity for parallel apply on the slave, but too high a value will decrease commit throughput', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL, 'NO', NULL),
